"use client";

import type { Source } from "@audio-ui/react";
import { type ReactNode, useEffect, useMemo, useRef } from "react";
import { cn } from "@/lib/utils";
import {
  Plot,
  PlotCurve,
  PlotDot,
  PlotGraph,
  PlotGrid,
  PlotLine,
} from "@/components/audio-ui/plot";
import {
  DevicePanel,
  DeviceToggle,
} from "@/components/audio-ui/device-panel";
import {
  type CompressorState,
  compressorCurve,
  compressorDevice,
} from "@/components/audio-ui/devices/compressor/device";

const MIN_DB = -60;
const MAX_DB = 6;
const DB_TICKS = [-48, -24, 0];
const UNITY = (inputDb: number) => inputDb;
/** What the knobs gather: the curve, the timing, the output. */
const GROUPS = [
  { label: "Curve", parameters: ["thresholdDb", "ratio", "kneeDb"] },
  { label: "Time", parameters: ["attackMs", "releaseMs"] },
  { label: "Output", parameters: ["makeupDb", "mix"] },
] as const;
const SWITCHES = ["enabled", "autoMakeup"] as const;
/** With auto make-up on, the node's own make-up plays and this knob does nothing. */
const MAKEUP_OFF = ["makeupDb"] as const;

interface CompressorPanelProps {
  /** Whatever the host puts next to the name: a play button, a reading. */
  children?: ReactNode;
  className?: string;
  /** The level going in, in dB, as a live source: a dot rides the curve at it. */
  level?: Source<number>;
  onValueChange: (state: CompressorState) => void;
  value: CompressorState;
}

/**
 * The face of the compressor device: its name and switches, the transfer curve
 * it plays with the threshold and the level going in on it, and its knobs
 * gathered by what they do. It is controlled like `DevicePanel`, which it uses
 * for the knobs: drawing the curve is all it adds. Its children sit in the
 * header, after the name.
 */
function CompressorPanel({
  children,
  className,
  level,
  onValueChange,
  value,
}: CompressorPanelProps) {
  const output = useMemo(() => compressorCurve(value), [value]);
  const dot = useMemo(
    () =>
      level && {
        getSnapshot: () => {
          const x = level.getSnapshot();
          return { x, y: output(x) };
        },
        subscribe: level.subscribe,
      },
    [level, output]
  );
  // The dot rides the curve while there is a signal; with none it has no place on it.
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const element = root.current;
    if (!(element && level)) {
      return;
    }
    const sync = () =>
      element.toggleAttribute("data-idle", level.getSnapshot() < MIN_DB);
    sync();
    return level.subscribe(sync);
  }, [level]);
  return (
    <div
      className={cn("group/compressor flex w-full flex-col gap-4", className)}
      data-idle=""
      data-slot="compressor-panel"
      ref={root}
    >
      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
        <div className="flex items-center gap-2">
          <span className="font-medium text-sm">{compressorDevice.name}</span>
          {children}
        </div>
        <div className="flex gap-1.5">
          {SWITCHES.map((id) => (
            <DeviceToggle
              device={compressorDevice}
              id={id}
              key={id}
              onValueChange={onValueChange}
              value={value}
            />
          ))}
        </div>
      </div>
      <Plot
        aria-label="Transfer curve"
        className="h-40"
        maxX={MAX_DB}
        maxY={MAX_DB}
        minX={MIN_DB}
        minY={MIN_DB}
      >
        <PlotGraph>
          <PlotCurve
            className="stroke-border [stroke-dasharray:4_4]"
            fn={UNITY}
          />
          <PlotLine
            axis="x"
            className="stroke-foreground/40"
            value={value.thresholdDb}
          />
          <PlotCurve fn={output} />
        </PlotGraph>
        <PlotGrid x={{ ticks: DB_TICKS }} y={{ ticks: DB_TICKS.slice(0, 2) }} />
        {dot ? (
          <PlotDot className="group-data-idle/compressor:hidden" source={dot} />
        ) : null}
      </Plot>
      <DevicePanel
        device={compressorDevice}
        disabled={value.autoMakeup ? MAKEUP_OFF : undefined}
        exclude={SWITCHES}
        groups={GROUPS}
        onValueChange={onValueChange}
        value={value}
      />
    </div>
  );
}

export { CompressorPanel };
